#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    /* 1. No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Convert the argument */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* 2a. Conversion failed or extra characters left */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Range check (the original program only checks the upper bound) */
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Sum of proper divisors */
    long sum = 0;
    for (long i = 1; i < n; ++i) {
        if (n % i == 0)
            sum += i;
    }

    /* 5. Classification */
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }

    return 0;
}
